/**
 * Discovers the routes generated by sample ("demo") content.
 *
 * Config-time helper used by astro.config.mjs to keep example pages out of
 * the sitemap. It reads the same Markdown frontmatter Astro will read, so
 * marking a file `demo: true` is enough — there is no second list to
 * maintain and get out of sync.
 */
import { readdir, readFile } from 'node:fs/promises';
import path from 'node:path';

const COLLECTIONS = ['projects', 'blog', 'writing'];

/** Read the YAML frontmatter block as a plain string (no parser needed). */
const frontmatter = (source) => source.match(/^---\n([\s\S]*?)\n---/)?.[1] ?? '';

const hasFlag = (fm, key) => new RegExp(`^${key}:\\s*true\\s*$`, 'm').test(fm);

async function walk(dir) {
  const entries = await readdir(dir, { withFileTypes: true }).catch(() => []);
  const files = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) files.push(...(await walk(full)));
    else if (/\.(md|mdx)$/.test(entry.name)) files.push(full);
  }
  return files;
}

/**
 * @param {string} contentDir absolute path to src/content
 * @returns {Promise<string[]>} URL paths (with trailing slashes) to exclude
 */
export async function getDemoPaths(contentDir) {
  const paths = new Set();

  for (const collection of COLLECTIONS) {
    const files = await walk(path.join(contentDir, collection));

    for (const file of files) {
      const source = await readFile(file, 'utf8');
      const fm = frontmatter(source);
      if (!hasFlag(fm, 'demo')) continue;

      const relative = path.relative(path.join(contentDir, collection), file).replace(/\\/g, '/');
      const withoutExt = relative.replace(/\.(md|mdx)$/, '');

      if (collection === 'projects') {
        paths.add(`/projects/${withoutExt}/`);
        continue;
      }

      if (collection === 'blog') {
        paths.add(`/blog/${withoutExt}/`);
        continue;
      }

      // Writing: books, chapters and standalone pieces live at different depths.
      const bookSlug = fm.match(/^book:\s*(.+)$/m)?.[1]?.trim();
      const isChapter = /^chapter:\s*\d+/m.test(fm);
      const isBook = /^kind:\s*book\s*$/m.test(fm);

      if (isChapter && bookSlug) {
        const chapter = withoutExt.split('/').pop();
        paths.add(`/writing/book/${bookSlug}/chapter/${chapter}/`);
      } else if (isBook && bookSlug) {
        paths.add(`/writing/book/${bookSlug}/`);
      } else {
        paths.add(`/writing/${withoutExt}/`);
      }
    }
  }

  return [...paths].sort();
}
